function collectVisibleDraft(draft,previous){const originalAnswers=copy(draft.answers);const s=copy(draft),item=previous.items[previous.currentIndex];if(!item||!document.getElementById('view-title')?.textContent.startsWith('문항 '))return s;if(previous.attempts.some(a=>a.instanceId===item.instanceId))return s;if(item.type==='written'){const selected=document.querySelector('input[name="written-answer"]:checked');if(selected)s.answers[item.instanceId]=selected.value;}else{const answer={...(s.answers[item.instanceId]||{})};for(const p of item.parts){if(p.kind==='text'){const input=$(`part-${p.partId}`);if(input)answer[p.partId]=input.value;}else{const selected=[...document.querySelectorAll('input')].filter(el=>el.name===p.partId&&el.checked).map(el=>el.value);if(p.kind==='multi')answer[p.partId]=selected;else if(selected.length)answer[p.partId]=selected[0];}}if($('free-response'))answer.freeResponse=$('free-response').value;s.answers[item.instanceId]=answer;}if(s.status!=='active'||s.attempts.some(a=>a.instanceId===item.instanceId)){s.recoveryDraft={answers:copy(s.answers),observedAt:Date.now(),reason:'저장 실패 중 화면에 남은 입력',excludedFromGrade:true};s.answers=originalAnswers;}return s;}
