async function retrySave(){if(!state.unsaved)return;try{let expired=false;state.session=await state.store.update(state.session.sessionId,state.session.revision,current=>{const t=nowState(current);expired=current.config.mode==='timed'&&t.expired;if(!expired)return state.unsaved;const result=finalize(current,'expired',t.now);result.recoveryDraft={answers:copy(state.unsaved.recoveryDraft?.answers||state.unsaved.answers),observedAt:Date.now(),reason:'마감 전 저장에 성공하지 못한 입력. 채점에서 제외하고 복구 자료로만 보존.',excludedFromGrade:true};return result;});state.storageFailed=false;state.unsaved=null;clearError();announce(expired?'제한 시간이 지나 마지막 저장 답안만으로 종료했습니다. 미저장 입력은 점수와 별도의 복구 초안으로 보존했습니다.':'미저장 입력을 저장했습니다.');renderSession();}catch(error){showError(error);}}
