    if(r.name==='setup')renderSetup(r.args.type,r.args.config||{});
    else if(r.name==='review')await renderWrong(r.args.sessionId||null);
    else if(r.name==='history')await renderHistory();
    else if(r.name==='bank')renderBank();
    else if(r.name==='manage')await renderManage();
    else if(r.name==='session'&&r.args.id){const opened=await openSession(r.args.id);if(request===state.routeRequest&&opened&&state.session?.sessionId===r.args.id&&(state.session.status!=='active'||state.editor?.acquired)){if(r.args.view==='finish'&&state.session.status==='active')await renderFinish();else if(r.args.view==='list'&&state.session.status==='active')await renderQuestionList();else if(r.args.view==='extend'&&state.session.status==='active')renderExtend();else if(r.args.view==='convert'&&state.session.status==='active')renderConvert();else if(['review','prompt'].includes(r.args.view)){const item=state.session.items.find(i=>i.instanceId===r.args.item);if(item){if(r.args.view==='review')await renderReview(state.session,item);else await renderPrompt(item);}}}}
