function showBackupDownloads(sessions,title='기록 백업 내보내기'){const parts=partitionBackups(sessions);if(parts.length===1&&parts[0].restorable){download(parts[0].filename,parts[0].content,'application/json');return;}screen(title,node('p',{},`전체 ${sessions.length}세션을 ${parts.length}개 파일로 나눴습니다. 각 버튼을 눌러 개별 파일을 내려받으세요. 자동으로 여러 다운로드를 시작하지 않습니다.`),node('p',{},'복원 가능한 파일은 각각 10MB 이하·1000세션 이하입니다. 모든 파일을 차례로 합치기 방식으로 가져오면 됩니다. 세션 ID를 보존하며 이미 가져온 기록은 중복 추가하지 않습니다.'),...parts.map((part,index)=>node('section',{class:part.restorable?'card':'notice'},node('h3',{},`파일 ${index+1} / ${parts.length}: ${part.restorable?'복원 가능한 백업':'원문 보존 전용 · 현재 앱으로 복원 불가'}`),node('p',{},`${part.sessionCount}세션 · ${(part.byteLength/1024/1024).toFixed(2)}MB`),node('p',{},part.reason),button(part.restorable?`${index+1}번 백업 내려받기`:`${index+1}번 원문 보존 파일 내려받기 (가져오기 불가)`,()=>download(part.filename,part.content,'application/json')))),actions(button(state.storageFailed?'미저장 문제로 돌아가기':'백업 설정으로 돌아가기',()=>state.storageFailed?renderSession():renderManage(),{class:'secondary'})));}

