    screen('백업 가져오기 확인',node('p',{},`파일: ${selected.name} · 검사 통과 ${parsed.sessions.length}개 연습 · 현재 기록 ${state.sessions.length}개`),node('p',{},replace?'교체하면 현재 브라우저의 연습과 답안을 모두 지우고 파일의 기록으로 바꿉니다. 백업하지 않은 현재 기록은 복구할 수 없습니다.':'합치면 현재 기록을 유지하고 새 기록만 추가합니다. 동일 ID나 내용이 다른 중복 ID는 현재 기록을 유지합니다.'),actions(button(replace?'현재 기록을 교체하고 가져오기':'현재 기록과 합치기',async event=>{if(replace&&!window.confirm(`현재 ${state.sessions.length}개 연습을 삭제하고 파일의 ${parsed.sessions.length}개로 교체합니다. 백업하지 않은 기록은 복구할 수 없습니다. 교체할까요?`))return;event.currentTarget.disabled=true;const generation=state.openGeneration;try{const result=await state.store.importSessions(parsed.sessions,replace);if(generation===state.openGeneration)await renderManage();announce(`${result.imported}개 연습을 가져왔습니다. 동일 기록 ${result.duplicates}개, 내용이 다른 중복 ID ${result.conflicts}개는 기존 기록을 유지했습니다.`);}catch(error){event.currentTarget.disabled=false;throw error;}}),button('취소하고 백업 설정으로',renderManage,{class:'secondary'})));
