function remainingText(ms){const seconds=Math.ceil((ms||0)/1000);return `남은 시간 ${Math.floor(seconds/60)}분 ${seconds%60}초`;}
let ticking=false;async function timerTick(){refreshSessionLinkLabels();if(ticking||state.leaving||state.opening||state.transitioning||state.converting||!state.session||state.session.status!=='active'||state.session.config.mode!=='timed'||!state.editor?.acquired)return;ticking=true;try{const s=state.session,t=nowState(s);if($('remaining'))$('remaining').textContent=remainingText(t.remaining);if(t.expired){if(!state.storageFailed)await edit((current)=>finalize(current,'expired',t.now));else announce('제한 시간이 끝났습니다. 저장 실패로 확정하지 못했습니다. 미저장 입력을 먼저 백업하고 저장을 다시 시도하세요.');return;}const thresholds=[600000,300000,60000];for(const value of thresholds){const key=`remaining-${value}`;if(s.config.minutes*60000>value&&t.remaining<=value&&!state.warningKeys.has(key)){state.warningKeys.add(key);await edit(current=>{if(!current.warnings.includes(key))current.warnings.push(key);return current;});if(state.settings.timerWarnings)announce(`제한 시간이 ${value/60000}분 이내로 남았습니다.`);}}if(!t.trusted&&s.clockTrusted){await edit(current=>{current.clockTrusted=false;return current;});announce('시스템 시계 차이가 감지되었습니다. 현재 탭은 단조 증가 시계를 사용하며 시간 신뢰를 낮게 표시합니다.');}}catch(error){showError(error);}finally{ticking=false;}}
window.addEventListener('pagehide',releaseEditor);document.addEventListener('visibilitychange',()=>{if(!document.hidden)timerTick();});window.addEventListener('beforeunload',event=>{if(state.storageFailed){event.preventDefault();event.returnValue='';}});
async function bootstrap(){history.replaceState({examRoute:{name:'home',args:{}}},'', '#home');installNavigation();try{state.store=await openStore();state.settings=await state.store.meta('settings')||state.settings;const cached=await state.store.meta('bank');if(cached){try{validateBank(cached.bank);state.bundle=cached;state.bank=cached.bank;updateContentNotice();}catch(error){showError(new Error('저장된 문제 은행이 손상되었습니다. 세션 스냅샷은 보존하며 새 은행을 확인합니다.'));}}await refreshSessions();for(const s of state.sessions.filter(s=>s.status==='active'&&s.config.mode==='timed')){const t=timeState(s,Date.now());if(t.expired)await state.store.update(s.sessionId,s.revision,current=>finalize(current,'expired',t.now));}await renderHome();await checkUpdate(false);if(state.view==='무엇을 연습할까요?')await renderHome();$('version').textContent=`앱 ${APP_VERSION} · 문제 은행 ${state.bank?.bankVersion||'불러오지 못함'}`;setInterval(timerTick,1000);}catch(error){showError(error);screen('저장소를 사용할 수 없습니다',node('p',{},'초기 저장을 보장할 수 없어 연습을 시작하지 않았습니다. 기존 브라우저 데이터를 지우지 말고 비공개 창·저장 공간·사이트 설정을 확인하세요.'),button('다시 시도',()=>location.reload()));}}
